'use strict';
const M=window.EssenceDemo,canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s);
let state=M.create(),images={},ready=false,paused=false,previous=0,width=0,height=0,scale=1,ox=0,oy=0,dpr=1,noticeId=0,messageUntil=0,raf=0,pointer=null,bankWasPending=false,bankExpected=0;
const keys=new Set(),touches=new Map(),reduced=matchMedia('(prefers-reduced-motion: reduce)');
const camera={x:510,y:490};
const assets={hero:'hero.png',rogue:'rogue.png',mage:'mage.png',grass:'grass.png',path:'path.png',stone:'stone.png',tree:'tree.png',tree2:'tree2.png',pine:'pine.png',portal:'portal.png',bank:'banking-coffer.png',essence:'essence-pickup.png',spell:'apocalipsis_60.png'};
const floor=document.createElement('canvas');floor.width=M.WIDTH;floor.height=M.HEIGHT;
function loadImage(name,file){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[name]=im;resolve();};im.onerror=()=>reject(Error(file));im.src='../assets/'+file;});}
async function load(){ready=false;$('#retry').hidden=true;$('#curtain').hidden=false;$('#curtain-title').textContent='Opening the portal…';try{await Promise.all(Object.entries(assets).map(([n,f])=>loadImage(n,f)));buildFloor();ready=true;$('#curtain').hidden=true;drawInventoryIcon();resize();showHelp(true);schedule();}catch(e){$('#curtain-title').textContent='The portal could not open';$('#curtain-text').textContent='An artwork file did not load. Please try again.';$('#retry').hidden=false;}}
function buildFloor(){const c=floor.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle=c.createPattern(images.grass,'repeat');c.fillRect(0,0,M.WIDTH,M.HEIGHT);c.save();c.beginPath();c.rect(130,400,860,100);c.rect(570,320,90,480);c.rect(150,470,95,220);c.clip();for(let y=0;y<M.HEIGHT;y+=40)for(let x=0;x<M.WIDTH;x+=40)c.drawImage(images.path,x,y,40,40);c.restore();for(let y=330;y<520;y+=40)for(let x=50;x<270;x+=40)c.drawImage(images.stone,x,y,40,40);const shade=c.createRadialGradient(580,450,100,580,450,780);shade.addColorStop(0,'#203a2610');shade.addColorStop(1,'#03120ed9');c.fillStyle=shade;c.fillRect(0,0,M.WIDTH,M.HEIGHT);}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;scale=width<760?Math.max(.72,Math.min(width/560,height/760)):Math.min(width/1100,height/790);schedule();}
function ellipse(x,y,rx,ry,color,line=false){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);if(line){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke();}else{ctx.fillStyle=color;ctx.fill();}}
function text(s,x,y,color='#e6e4cc',size=13){ctx.font=`${size}px Inter, sans-serif`;ctx.textAlign='center';ctx.fillStyle='#07120f';ctx.fillText(s,x+1,y+2);ctx.fillStyle=color;ctx.fillText(s,x,y);}
function actor(a,body,player=false){const im=images[body];const f=a.moving?1+Math.floor(a.gait/64*7)%7:0;ellipse(a.x,a.y+1,16,5,'#00110cc0');if(player)ellipse(a.x,a.y+2,20,8,'#e8d491',true);ctx.drawImage(im,f*96,a.dir*160,96,160,Math.round(a.x-30),Math.round(a.y-91),60,100);}
function portal(){const frame=reduced.matches?0:Math.floor(state.time*10)%8;const p=M.gateway;ctx.save();ctx.shadowColor='#bddd66';ctx.shadowBlur=reduced.matches?0:22;ctx.drawImage(images.portal,(frame%4)*240,Math.floor(frame/4)*320,240,320,p.x-96,p.y-248,192,256);ctx.restore();text('RETURN TO NIX',p.x,p.y+32,'#d8e9b1',13);}
function draw(){if(!ready)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#091911';ctx.fillRect(0,0,width,height);const p=state.player;
 camera.x=p.x;camera.y=p.y;ox=width/2-p.x*scale;oy=height/2-p.y*scale;
 ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.imageSmoothingEnabled=false;ctx.drawImage(floor,0,0);
 text('NIX REFUGE',164,590,'#b3bc9a',11);
 for(const e of state.enemies){if(state.phase!=='arena'||e.hp<=0)continue;if(e.wind>0){ellipse(e.x,e.y,70*(1-e.wind/.85),27*(1-e.wind/.85),'#e7966955');ellipse(e.x,e.y,70,27,'#f0a16a',true);}else ellipse(e.x,e.y+2,25,10,'#db9b6655',true);}
 const layers=[...M.scenery.map(s=>({...s,type:'scenery'})),{type:'portal',y:M.gateway.y},...(state.bankUnlocked?[{type:'bank',y:M.banker.y}]:[]),...(state.phase==='arena'?state.enemies.filter(e=>e.hp>0):[]),{...p,body:'hero',player:true}].sort((a,b)=>a.y-b.y);
 for(const a of layers){if(a.type==='scenery')ctx.drawImage(images[a.id],a.x-a.w/2,a.y-a.h,a.w,a.h);else if(a.type==='portal')portal();else if(a.type==='bank'){ctx.drawImage(images.bank,230,255,1075,555,M.banker.x-54,M.banker.y-46,108,56);text('ESSENCE BANK',M.banker.x,M.banker.y+28,'#bdc7a8',11);}else actor(a,a.body,a.player);}
 if(state.phase==='arena')for(const e of state.enemies){if(e.hp<=0)continue;text(e.name,e.x,e.y-98,'#d9c79c',12);const max=e.maxHp;ctx.fillStyle='#16251b';ctx.fillRect(e.x-21,e.y-91,42,4);ctx.fillStyle=e.wind?'#f2a16c':'#cbad70';ctx.fillRect(e.x-21,e.y-91,42*e.hp/max,4);}
 for(const f of state.fx){const frame=Math.min(31,Math.floor(f.age*16));if(f.owner==='melee'){if(f.age<.25)ellipse(f.x,f.y,20+f.age*30,8+f.age*15,'#e8d5a7',true);}else if(reduced.matches){ellipse(f.x,f.y,35,20,'#e8d5a7',true);}else ctx.drawImage(images.spell,(frame%4)*273,Math.floor(frame/4)*243,273,243,f.x-73,f.y-90,146,130);}
 for(const drop of state.drops){
    ellipse(drop.x,drop.y+3,13,5,'#00190faa');
    ctx.drawImage(images.essence,300,230,480,1010,drop.x-7,drop.y-26,14,29);
    text(String(drop.amount),drop.x,drop.y-38,drop.owner==='player'?'#f4d595':'#bce8b2',12);
  }
  const aim=aimPoint();
  if(aim&&state.armed){const valid=Math.hypot(aim.x-p.x,aim.y-p.y)<=270&&M.lineClear(p,aim);ellipse(aim.x,aim.y,34,17,valid?'#e4d490':'#dd8068',true);ctx.strokeStyle=valid?'#e4d490':'#dd8068';ctx.beginPath();ctx.moveTo(aim.x-10,aim.y);ctx.lineTo(aim.x+10,aim.y);ctx.moveTo(aim.x,aim.y-9);ctx.lineTo(aim.x,aim.y+9);ctx.stroke();}
  for(const e of state.enemies)if(e.wind>0&&e.kind==='ranged'&&e.aim){ellipse(e.aim.x,e.aim.y,42,20,'#f1a373',true);}
 if(state.carried){text(`✦ ${state.carried}`,p.x,p.y-112,'#f3d586',15);}
 if(state.meditating){ellipse(p.x,p.y,26,11,'#82bddf',true);text('MEDITATING',p.x,p.y-104,'#a2d1e4',11);}
 ctx.setTransform(dpr,0,0,dpr,0,0);if(state.flash&&!reduced.matches){ctx.fillStyle=`rgba(200,230,158,${state.flash*.35})`;ctx.fillRect(0,0,width,height);}
}
function ui(){
 const p=state.player;$('#health-fill').style.width=p.hp+'%';$('#health').textContent=Math.ceil(p.hp)+' / 100';$('#mana-fill').style.width=p.mana+'%';$('#mana').textContent=Math.floor(p.mana)+' / 100';$('#mobile-vitals').textContent='Life '+Math.ceil(p.hp)+' · Mana '+Math.floor(p.mana);$('#carried').textContent=state.carried;$('#secured').textContent=state.secured;
 $('#chapter').textContent='THE VEIL / TRAINING GROUNDS';$('#objective-label').textContent=state.won?'THE LOOP IS YOURS':'SECURE 60 ESSENCE';
 $('#objective').textContent=state.won?'Goal complete':state.carried?'Return with your essence':state.drops.length?'Pick up the crystal':'The Veil';
 $('#hint').textContent=state.carried?'Deposit at the reliquary, south of the return portal. Fall and you drop what you carry.':state.drops.length?'Stand on a crystal and press Q. Your dropped essence can be recovered.':`Prepare Apocalipsis, then point and click a rival. ${state.secured} / 60 secured.`;
 const near=M.nearBank(state),gate=M.nearGate(state),item=state.drops.some(d=>Math.hypot(d.x-p.x,d.y-p.y)<=22);
 $('.interact-area').hidden=!(near||gate||item||state.bank);
 $('#interact').disabled=state.bank>0||paused;
 $('#interact').innerHTML=state.bank?'Depositing…':item?'Pick up essence <kbd>Q</kbd>':near?'Open essence bank <kbd>E</kbd>':'Return to Nix <kbd>E</kbd>';
 $('#bank-progress').hidden=!state.bank;$('#bank-progress span').style.width=Math.min(100,state.bank/1.5*100)+'%';$('#cast').disabled=paused;$('#meditate').setAttribute('aria-pressed',String(state.meditating));$('#meditate').textContent=state.meditating?'Meditating… N to stop':'Meditate · N';$('#prepare-spell').disabled=paused;$('#prepare-spell').textContent=state.armed?'Apocalipsis ready · click a rival':'Prepare Apocalipsis · C';$('#prepare-spell').setAttribute('aria-pressed',String(state.armed));$('#cast').setAttribute('aria-pressed',String(state.armed));$('#target-help').textContent=state.armed?'Apocalipsis ready · click a rival · Esc cancels':'C to prepare · Q to pick up · P for controls';$('#spell-status').textContent=state.armed?'Ready: click your target':'Prepare, then click a rival';$('#inventory-count').textContent=state.carried;$('#essence-slot').disabled=state.carried===0;$('#item-description').textContent=state.carried?state.carried+' essence carried. Deposit it at the bank to keep it safe.':'No essence carried. Pick up a crystal with Q.';canvas.style.cursor=state.armed?'crosshair':'default';$('#cast').style.opacity=state.cooldown>0?'.55':'1';
 updateBankDialog();
 if(state.noticeId!==noticeId){noticeId=state.noticeId;$('#message').textContent=state.notice;messageUntil=performance.now()+5000;}$('#message').classList.toggle('visible',performance.now()<messageUntil);
}
function input(){if($('#bank-dialog').open||$('#help-dialog').open)return {x:0,y:0};const last=[...keys].filter(k=>k!==' ').at(-1);return last==='d'||last==='arrowright'?{x:1,y:0}:last==='a'||last==='arrowleft'?{x:-1,y:0}:last==='w'||last==='arrowup'?{x:0,y:-1}:last==='s'||last==='arrowdown'?{x:0,y:1}:{x:0,y:0};}
function aimPoint(){if(!pointer)return null;const point={x:state.player.x+(pointer.x-width/2)/scale,y:state.player.y+(pointer.y-height/2)/scale};const hit=state.enemies.filter(e=>e.hp>0&&Math.abs(e.x-point.x)<28&&point.y>=e.y-88&&point.y<=e.y+8).sort((a,b)=>b.y-a.y)[0];return hit?{x:hit.x,y:hit.y,enemyId:hit.name}:point;}
function prepareSpell(){if(!ready||paused)return;document.body.classList.remove('hud-open');$('#toggle-hud').setAttribute('aria-expanded','false');state.armed=true;M.tell(state,'Apocalipsis ready. Point at a rival and click. Esc cancels.');canvas.focus({preventScroll:true});}
function castAtPointer(){const point=aimPoint();if(point)M.cast(state,point);else M.tell?.(state,'Point at the world to aim.');}
function interact(){const action=M.interact(state);if(action==='exit')window.location.assign('../#home');else if(action==='bank')openBank();}

function tick(now){raf=0;const dt=Math.min((now-previous)/1000||0,.04);previous=now;if(ready&&!paused&&!document.hidden){M.update(state,dt,input());}draw();ui();if(ready&&!document.hidden)schedule();}
function schedule(){if(!raf&&!document.hidden)raf=requestAnimationFrame(tick);}
function clear(){keys.clear();touches.clear();}
function showHelp(first=false){if(!ready)return;clear();paused=true;$('#help-title').textContent=first?'Welcome to the Veil':'Paused';$('#resume').textContent=first?'Enter the Veil':'Resume';$('#pause').setAttribute('aria-pressed','true');if(!$('#help-dialog').open)$('#help-dialog').showModal();}
function hideHelp(){if($('#help-dialog').open)$('#help-dialog').close();paused=false;$('#pause').setAttribute('aria-pressed','false');document.body.classList.add('portal-arrival');canvas.focus({preventScroll:true});previous=performance.now();schedule();}
function togglePause(value=!paused){if(!ready||$('#bank-dialog').open)return;if(value)showHelp();else hideHelp();}
function drawInventoryIcon(){const c=$('#inventory-crystal').getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,36,44);c.drawImage(images.essence,300,230,480,1010,8,0,20,42);}
function selectHudTab(name){for(const tab of ['spells','inventory']){const active=name===tab;$('#'+tab+'-tab').setAttribute('aria-selected',String(active));$('#'+tab+'-tab').tabIndex=active?0:-1;$('#'+tab+'-panel').hidden=!active;}}
function openBank(){if(!M.nearBank(state)||!state.bankUnlocked){M.tell(state,'Approach the essence bank first.');return;}clear();state.player.step=null;$('#deposit-amount').value=state.carried||'';$('#bank-receipt').textContent='Choose how much to secure.';bankWasPending=false;$('#bank-dialog').showModal();updateBankDialog();}
function closeBank(){M.cancelDeposit(state);bankWasPending=false;if($('#bank-dialog').open)$('#bank-dialog').close();clear();canvas.focus({preventScroll:true});}
function updateBankDialog(){if(!$('#bank-dialog').open)return;$('#bank-carried').textContent=state.carried;$('#bank-secured').textContent=state.secured;$('#deposit-amount').max=state.carried;const amount=Number($('#deposit-amount').value);$('#confirm-deposit').disabled=!!state.bank||!Number.isInteger(amount)||amount<1||amount>state.carried;$('#deposit-amount').disabled=!!state.bank;$('#deposit-all').disabled=!!state.bank||!state.carried;if(state.bank){$('#bank-receipt').textContent='Depositing '+state.bankAmount+' essence…';bankWasPending=true;}else if(bankWasPending){$('#bank-receipt').textContent=state.secured>=bankExpected?'Deposited. Your secured essence is safe.':'Deposit cancelled. Your essence is still carried.';$('#deposit-amount').value=state.carried||'';bankWasPending=false;}}

const accepted=['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'];document.addEventListener('keydown',e=>{if($('#help-dialog').open||$('#bank-dialog').open)return;if(e.ctrlKey||e.metaKey||e.altKey)return;const key=e.key.toLowerCase();if(key==='escape'&&state.armed){state.armed=false;M.tell(state,'Spell cancelled.');return;}if(key==='p'||key==='escape'){if(!e.repeat)togglePause();return;}if(e.target.closest('button,a,input,select,textarea'))return;if(accepted.includes(key)){e.preventDefault();if(ready&&!paused&&!e.repeat){keys.delete(key);keys.add(key);}}if(key==='c'&&!e.repeat&&ready&&!paused){e.preventDefault();prepareSpell();}if(key===' '&&!e.repeat&&ready&&!paused){e.preventDefault();M.melee(state);}if(key==='q'&&!e.repeat&&ready&&!paused){if(!M.pickup(state,22))M.tell(state,'Stand on a dropped crystal, then press Q.');}if(key==='n'&&!e.repeat&&ready&&!paused){clear();M.meditate(state);}if(key==='e'&&!e.repeat&&ready&&!paused)interact();});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
const mapping={up:'w',left:'a',down:'s',right:'d'};for(const button of document.querySelectorAll('[data-dir]')){button.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||!ready)return;button.setPointerCapture(e.pointerId);touches.set(e.pointerId,mapping[button.dataset.dir]);keys.add(mapping[button.dataset.dir]);});const release=e=>{const key=touches.get(e.pointerId);touches.delete(e.pointerId);if(![...touches.values()].includes(key))keys.delete(key);};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);}
$('#cast').addEventListener('click',prepareSpell);$('#prepare-spell').onclick=prepareSpell;$('#strike').onclick=()=>{if(ready&&!paused)M.melee(state);canvas.focus({preventScroll:true});};$('#meditate').onclick=()=>{if(ready&&!paused){clear();M.meditate(state);}canvas.focus({preventScroll:true});};
$('#interact').onclick=()=>{if(ready&&!paused)interact();canvas.focus({preventScroll:true});};$('#pause').onclick=()=>togglePause();$('#resume').onclick=hideHelp;$('#restart').onclick=()=>{if(!ready)return;state=M.create();pointer=null;noticeId=0;messageUntil=0;hideHelp();};$('#retry').onclick=load;
function locatePointer(e){const rect=canvas.getBoundingClientRect();pointer={x:e.clientX-rect.left,y:e.clientY-rect.top};}
canvas.addEventListener('pointermove',locatePointer);
canvas.addEventListener('click',e=>{canvas.focus({preventScroll:true});locatePointer(e);if(ready&&!paused){const world={x:state.player.x+(pointer.x-width/2)/scale,y:state.player.y+(pointer.y-height/2)/scale};if(!state.armed&&state.bankUnlocked&&Math.abs(world.x-M.banker.x)<60&&world.y>M.banker.y-55&&world.y<M.banker.y+14){openBank();return;}if(state.armed)castAtPointer();else{const hit=aimPoint();M.tell(state,hit?.enemyId?hit.enemyId+' · prepare Apocalipsis with C to cast.':'Prepare a spell first, then point and click.');}}});window.addEventListener('blur',()=>{clear();if(ready&&!paused)togglePause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden){clear();if(ready&&!paused)togglePause(true);if(raf)cancelAnimationFrame(raf);raf=0;}else{previous=performance.now();schedule();}});window.addEventListener('resize',resize);resize();load();

$('#hud-help').onclick=()=>showHelp();$('#close-help').onclick=hideHelp;$('#help-dialog').addEventListener('cancel',e=>{e.preventDefault();hideHelp();});
$('#toggle-hud').onclick=()=>{const open=document.body.classList.toggle('hud-open');$('#toggle-hud').setAttribute('aria-expanded',String(open));clear();};
for(const tab of ['spells','inventory']){$('#'+tab+'-tab').onclick=()=>selectHudTab(tab);$('#'+tab+'-tab').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const other=tab==='spells'?'inventory':'spells';selectHudTab(other);$('#'+other+'-tab').focus();}});}
$('#essence-slot').onclick=()=>selectHudTab('inventory');$('#deposit-all').onclick=()=>{$('#deposit-amount').value=state.carried;updateBankDialog();};$('#deposit-amount').addEventListener('input',updateBankDialog);
$('#deposit-form').addEventListener('submit',e=>{e.preventDefault();const amount=Number($('#deposit-amount').value);if(M.beginDeposit(state,amount)){bankExpected=state.secured+amount;bankWasPending=true;}else $('#bank-receipt').textContent='Choose a valid amount while you are beside the bank.';updateBankDialog();});
$('#close-bank').onclick=closeBank;$('#cancel-bank').onclick=closeBank;$('#bank-dialog').addEventListener('cancel',e=>{e.preventDefault();closeBank();});
